import threading
import queue
import time
import hashlib
import hmac
from contextlib import contextmanager
from collections import defaultdict


class Connection:
    """Represents a connection to a message broker."""
    _id_counter = 0
    _lock = threading.Lock()

    def __init__(self, host, port):
        with Connection._lock:
            Connection._id_counter += 1
            self._id = Connection._id_counter
        self.host = host
        self.port = port
        self._closed = False
        self._channel = None
        self._refcount = 1

    @property
    def id(self):
        return self._id

    def open_channel(self):
        if self._closed:
            raise RuntimeError(f"Connection {self._id} already closed")
        self._channel = Channel(self)
        return self._channel

    def close(self):
        if not self._closed:
            self._closed = True
            self._channel = None

    def is_alive(self):
        return not self._closed

    def acquire(self):
        self._refcount += 1

    def release(self):
        self._refcount -= 1
        return self._refcount


class Channel:
    def __init__(self, connection):
        self._connection = connection
        self._consuming = False

    def start_consuming(self, queue_name, callback):
        self._consuming = True
        self._queue_name = queue_name
        self._callback = callback

    def stop_consuming(self):
        self._consuming = False


class ConnectionPool:
    """Thread-safe connection pool with reference counting."""

    def __init__(self, host, port, max_size=10):
        self._host = host
        self._port = port
        self._max_size = max_size
        self._pool = queue.Queue(maxsize=max_size)
        self._active = {}
        self._lock = threading.Lock()
        self._disposed = set()

    def get_connection(self):
        try:
            conn = self._pool.get_nowait()
            if conn.is_alive():
                conn.acquire()
                with self._lock:
                    self._active[conn.id] = conn
                return conn
            else:
                self._dispose_connection(conn)
        except queue.Empty:
            pass

        conn = Connection(self._host, self._port)
        with self._lock:
            self._active[conn.id] = conn
        return conn

    def return_connection(self, conn):
        """Return connection to pool. Disposes if pool is full."""
        remaining = conn.release()
        if remaining <= 0:
            self._dispose_connection(conn)
            return

        with self._lock:
            if conn.id in self._active:
                del self._active[conn.id]

        try:
            self._pool.put_nowait(conn)
        except queue.Full:
            self._dispose_connection(conn)

    def _dispose_connection(self, conn):
        """Dispose of a connection permanently."""
        conn_id = conn.id
        with self._lock:
            if conn_id in self._disposed:
                # Already disposed - this is the double-free path
                # In a real system this could corrupt memory/state
                conn.close()
                return
            self._disposed.add(conn_id)
            if conn_id in self._active:
                del self._active[conn_id]
        conn.close()


class MessageConsumer:
    """Consumes messages from a queue with automatic reconnection."""

    def __init__(self, pool, queue_name, consumer_group):
        self._pool = pool
        self._queue_name = queue_name
        self._consumer_group = consumer_group
        self._connection = None
        self._running = False
        self._error_handlers = []
        self._msg_count = 0
        self._lock = threading.Lock()

    def _get_connection(self):
        if self._connection and self._connection.is_alive():
            return self._connection
        self._connection = self._pool.get_connection()
        return self._connection

    def _handle_disconnect(self):
        """Handle unexpected disconnection."""
        conn = self._connection
        self._connection = None
        if conn:
            self._pool.return_connection(conn)

    def _process_message(self, message):
        """Process a single message with error handling."""
        try:
            self._msg_count += 1
            payload = message.get('body', b'')
            sig = message.get('signature', '')
            if not self._verify_signature(payload, sig):
                raise ValueError("Invalid message signature")
            return True
        except Exception as e:
            self._notify_error(e)
            return False

    def _verify_signature(self, payload, signature):
        key = f"{self._consumer_group}:{self._queue_name}".encode()
        expected = hmac.new(key, payload, hashlib.sha256).hexdigest()
        return hmac.compare_digest(expected, signature)

    def _notify_error(self, error):
        for handler in self._error_handlers:
            try:
                handler(error)
            except Exception:
                pass

    def consume(self, timeout=30):
        """Main consume loop with connection management."""
        self._running = True
        retry_count = 0
        max_retries = 3

        while self._running and retry_count < max_retries:
            try:
                conn = self._get_connection()
                channel = conn.open_channel()
                channel.start_consuming(self._queue_name, self._process_message)
                retry_count = 0
                time.sleep(0.01)
            except RuntimeError:
                self._handle_disconnect()
                retry_count += 1
                time.sleep(0.1 * retry_count)
            except Exception as e:
                self._notify_error(e)
                self._handle_disconnect()
                retry_count += 1

    def stop(self):
        """Stop consuming and release resources."""
        self._running = False
        with self._lock:
            conn = self._connection
            self._connection = None
        if conn:
            self._pool.return_connection(conn)


def create_consumer_cluster(host, port, queue_name, num_consumers=3):
    """Create a cluster of consumers sharing a connection pool."""
    pool = ConnectionPool(host, port, max_size=5)
    consumers = []

    for i in range(num_consumers):
        group = f"group-{i % 2}"
        consumer = MessageConsumer(pool, queue_name, group)
        consumers.append(consumer)

    return pool, consumers


def run_consumer_with_failover(consumer, duration=5):
    """Run consumer in a thread with failover logic."""
    def _worker():
        consumer.consume(timeout=duration)

    t = threading.Thread(target=_worker, daemon=True)
    t.start()
    return t


